/* ==========================================================================
   United States Universities For Ukraine — aid-data.js

   International-applicant financial aid policy dataset for the Financial
   Aid Finder (financial-aid-finder.html; logic in js/tools.js module 14).

   TIME-SENSITIVE DATA — this is NOT a build-once asset. International aid
   policy changes yearly and several schools are mid-transition. Re-verify
   every admissions cycle (annually at minimum) and bump `verified`.
   Every row carries its own `src` + verification date and an official
   `url`; the tool sends students to the primary source, it is not the
   last word. Fields per school:
     policy   'blind'|'aware'|'none'  need policy for INTERNATIONAL applicants
     fullNeed 'yes'|'partial'|'no'|'unconfirmed'  meets 100% intl need
     loans    'no-loan'|'loans'|'unknown'
     conf     'high' (verified on official page) | 'medium' (secondary)
     transition  non-null only when policy recently changed/changing
   ADMISSIONS BLOCK (`adm`) — added v16 for the College List Builder.
   Same file on purpose: the aid finder and the match engine must never
   disagree about one school. Fields (null = not yet verified, which the
   match engine surfaces as "insufficient data" rather than guessing):
     sat25/sat75  25th/75th percentile TOTAL SAT of admitted students
     act25/act75  25th/75th percentile ACT composite
     gpaAvg       published average/median admitted GPA (null if unpublished)
     gpaScale     'unweighted'|'weighted' — the engine ONLY compares a
                  student's 4.0 GPA against an 'unweighted' average, never
                  against a weighted one (that comparison would be invalid)
     setting      'urban'|'suburban'|'rural'
     noEngineering  true when the school has no undergrad engineering at all
     admSrc       source + verification date (required alongside any value)
     admConf      'high' (CDS/official class profile) | 'medium' (aggregator)
   TWO GENERATIONS OF ROWS, v21 (August 2026). The first 72 rows were
   researched school by school and carry 2025-26 or 2026-27 cost figures read
   off each school's own page. The 120 rows added in v21 take their
   admissions and cost figures from IPEDS 2023-24 — the U.S. Department of
   Education's own collection, which every school reports to by law — and
   only their aid-policy fields from the school's own site. That is why those
   rows say `"year": "2023-24"` and `coaConf: "medium"`: the figures are
   official but two years older, and the card shows the year so nobody
   compares a 2023-24 total against a 2025-26 one without noticing.
   A school is in this file ONLY if its own website states what it does about
   need-based aid for international undergraduates. 145 of the 265 candidates
   researched for v21 said nothing findable on their own site and were left
   out rather than guessed at — the tooling that produced these rows lives in
   the session scratchpad and the README explains how to finish the tail.

   COST-OF-ATTENDANCE BLOCK (`coa`) — added v19 for the Funding Gap
   Calculator. Third tool on the same file, same reason: the aid finder,
   the match engine and the funding calculator must never quote three
   different numbers for one school. Fields:
     year         academic year the figures are labelled with at source
     tuitionFees  tuition + required fees, USD
     livingOther  room, board, books, insurance, personal, travel, USD
     total        the school's OWN published total cost of attendance —
                  normally the exact figure it requires a student to
                  document for the I-20. Null ⇒ the calculator says
                  "insufficient data", never a national average.
     intlAvgAid   typical first-year award to INTERNATIONAL undergrads.
                  NULL FOR EVERY SCHOOL BUT ONE: only Harvard publishes a
                  figure this specific, in its own Common Data Set. None of
                  the others publishes an
                  international-specific average (several publish an
                  all-students average, which is a different number and
                  was deliberately not substituted). Consequence: without
                  a student-entered award letter the calculator returns
                  "insufficient data" for net cost — see §8 of HANDOFF.md.
     loansOk      true/false only when the school's own international
                  office page lists or excludes an education loan among
                  accepted I-20 funding sources. NULL THROUGHOUT — those
                  pages were not reachable in the research pass. The
                  calculator counts a loan when this is null and says so
                  on the card rather than silently assuming.
     i20Note      present only when the I-20 figure differs from the
                  standard published COA (3 schools)
     coaSrc       source + verification date (required alongside values)
     coaConf      'high' (read off the school's own page, 62 rows) |
                  'medium' (secondary source, 10 rows — the school's own
                  page returned 403 or rendered client-side)
   COA changes every single year. Re-verify annually with `verified`.
   Compiled by a research pass, July 2026; spot-check before each refresh.
   Admissions provenance, stated plainly: score ranges for most schools
   come from a single consistent testing-policy aggregator rather than
   from each school's raw Common Data Set PDF, so nearly every row is
   admConf "medium" — the tool shows that caveat on the card and sends
   students to the school's own page. Upgrading a row to "high" means
   reading that school's CDS directly. No average GPA is published by
   these schools in a verifiable form, so gpaAvg is null throughout
   rather than estimated (the engine simply falls back to test ranges).
   ========================================================================== */

